head.script:
// [FAIL] 증상 ① body.setDisabled(true)  : body 에만 disabled 가 적용되고 자식 컴포넌트로 전파되지 않는다.
//        증상 ② body.setReadOnly(true)  : body 에만 readonly 가 적용되고 자식 컴포넌트로 전파되지 않는다.

// 현재 적용 중인 증상 ("D" : setDisabled / "R" : setReadOnly)
scwin.strMode = "";

scwin.onpageload = function () {
    child_input.setValue("입력값");
    child_textarea.setValue("입력값");
    child_select.setSelectedIndex(0);
    child_calendar.setValue("20260730");
};



// body 컴포넌트 조회 (body 는 root 요소이므로 자식의 parentControl 로 조회한다.)
scwin.getBody = function () {
    return grp_main.parentControl;
};

// 자식 입력 컴포넌트 4 종
scwin.getChildList = function () {
    return [child_input, child_textarea, child_select, child_calendar];
};

// 자식 4 종의 getDisabled() / getReadOnly() 반환값 문자열
scwin.joinChildState = function (strApi) {
    var arrChild = scwin.getChildList();
    var arrState = [];

    for (var i = 0; i < arrChild.length; i++) {
        arrState.push(String(strApi === "D" ? arrChild[i].getDisabled() : arrChild[i].getReadOnly()));
    }

    return arrState.join(" / ");
};

// body / 자식 상태 초기화
scwin.resetAll = function () {
    var objBody = scwin.getBody();
    objBody.setDisabled(false);
    objBody.setReadOnly(false);

    var arrChild = scwin.getChildList();
    for (var i = 0; i < arrChild.length; i++) {
        arrChild[i].setDisabled(false);
        arrChild[i].setReadOnly(false);
    }
};



// (증상 ①) body 에 setDisabled(true)
scwin.btn_disabled_onclick = function () {
    scwin.resetAll();

    var objBody = scwin.getBody();
    objBody.setDisabled(true);
    var strAttr = objBody.render.getAttribute("disabled");

    scwin.setReturnValue("■ 증상 ① body.setDisabled(true)");
    scwin.setReturnValue("   body 자신  : getDisabled()=" + objBody.getDisabled()
        + " / DOM disabled 속성=" + (strAttr === null ? "(없음)" : strAttr) + "   (적용됨)");
    scwin.setReturnValue("   자식 4 종  : getDisabled()=" + scwin.joinChildState("D")
        + "   (기대 true / 실제 false → 전파 안 됨)");

    scwin.strMode = "D";
};



// (증상 ②) body 에 setReadOnly(true)
scwin.btn_readonly_onclick = function () {
    scwin.resetAll();

    var objBody = scwin.getBody();
    objBody.setReadOnly(true);
    var strAttr = objBody.render.getAttribute("readonly");

    scwin.setReturnValue("■ 증상 ② body.setReadOnly(true)");
    scwin.setReturnValue("   body 자신  : getReadOnly()=" + objBody.getReadOnly()
        + " / DOM readonly 속성=" + (strAttr === null ? "(없음)" : strAttr) + "   (적용됨)");
    scwin.setReturnValue("   자식 4 종  : getReadOnly()=" + scwin.joinChildState("R")
        + "   (기대 true / 실제 false → 전파 안 됨)");

    scwin.strMode = "R";
};



// 자식 컴포넌트의 실제 조작 결과 출력
scwin.printAct = function (strName, strAct) {
    if (scwin.strMode === "") {
        return;
    }

    scwin.setReturnValue("   실제 조작  : " + strName + " " + strAct + "   (기대 차단 / 실제 동작함)");
};

scwin.child_input_onclick = function (e) {
    if (scwin.strMode === "D") {
        scwin.printAct("input", "클릭됨");
    }
};

scwin.child_input_onviewchange = function (info) { scwin.printAct("input", "값 변경 → \"" + info.newValue + "\""); };
scwin.child_textarea_onviewchange = function (info) { scwin.printAct("textarea", "값 변경 → \"" + info.newValue + "\""); };
scwin.child_select_onviewchange = function (info) { scwin.printAct("selectbox", "값 변경 → \"" + info.newValue + "\""); };
scwin.child_calendar_onviewchange = function (info) { scwin.printAct("inputCalendar", "값 변경 → \"" + info.newValue + "\""); };



// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
